function renderAgentLifecycle(state,enabled){if(typeof enabled==='boolean'){S.agentAutoIntegrate=enabled;document.getElementById('chkAgentAutoIntegrate').checked=enabled}state=state&&typeof state==='object'?state:{};S.agentLifecycle=state;const phase=typeof state.phase==='string'?state.phase:'';document.getElementById('agentLifecyclePhase').textContent=Object.prototype.hasOwnProperty.call(S.agentPhases,phase)?S.agentPhases[phase]:S.agentUnknown;document.getElementById('agentLifecycleMessage').textContent=typeof state.message==='string'?state.message:''}
renderAgentLifecycle(S.agentLifecycle,S.agentAutoIntegrate);
window.addEventListener('message',function(event){const msg=event.data||{};if(msg.command==='agentLifecycle')renderAgentLifecycle(msg.state,msg.enabled)});
